       "label": "Validate Parent-Child Relationships",
       "children": [
         {
           "id": "c2",
           "label": "Ensure that all parent and child configurations reflect the actual hierarchy."
         },
         {
           "id": "c3",
           "label": "Use the CMDB Relationship Editor to make corrections."
         },
         {
           "id": "c1",
           "label": "Open the Parent-Child Relationships section in the software model record."
         }
       ]
     },
     {
       "id": "2",
       "label": "Access the Software Models List",
       "children": [
         {
           "id": "c2",
           "label": "Use the filter to locate uncertified software models."
         },
         {
           "id": "c1",
           "label": "Navigate to the Software Models module in the ServiceNow platform."
         }
       ]
     },
     {
       "id": "3",
       "label": "Check License Under Management (LUM)",
       "children": [
         {
           "id": "c2",
           "label": "Review the License Management report for any violations."
         },
         {
           "id": "c1",
           "label": "Confirm that the software model is compliant with license usage policies."
         }
       ]
     },
     {
       "id": "4",
       "label": "Verify DMAP (Discovery Map)",
       "children": [
         {
           "id": "c2",
           "label": "Ensure that all discrepancies are resolved, and mappings are accurate."
         },
         {
           "id": "c1",
           "label": "Open the software model record and review the DMAP field."
         },
         {
           "id": "c3",
           "label": "Use the Discovery Map Analyzer for troubleshooting if needed."
         }
       ]
     },
     {
       "id": "5",
       "label": "Review Inference Percentage",
