           "id": "c3",
           "label": "Use the Normalization Suggestions feature to improve accuracy."
         },
         {
           "id": "c2",
           "label": "Ensure that it meets the acceptable threshold (e.g., >90%)."
         },
         {
           "id": "c1",
           "label": "Check the Inference Percentage for the software model."
         }
       ]
     },
     {
       "id": "6",
       "label": "Certify Downgrade Rights",
       "children": [
         {
           "id": "c2",
           "label": "Ensure that the rights comply with the license terms and conditions."
         },
         {
           "id": "c1",
           "label": "Verify the downgrade rights for the software product."
